package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class YearFourNumberLinesTest {
 @Test public void all12221VisibleConditionsCoverEveryValueThrough10000(){int count=0;Set<Integer> values=new HashSet<>();for(int step:new int[]{1,10,100,1000})for(int start=0;start+10*step<=10000;start+=10*step)for(int mark=0;mark<=10;mark++){Question q=NumberLineRelations.make(start,step,mark);int answer=start+step*mark;q.answers=new String[]{"poison"};q.expression="poison";assertNotNull(NumberLineRelations.read(q));assertTrue(new Checker().check(q,List.of(),List.of(""+answer)).correct());assertEquals(Checker.Status.WRONG_ANSWER,new Checker().check(q,List.of(),List.of(""+(answer+1))).status);HelpPlan p=HelpPlan.forQuestion(q);assertFalse(p.canTransfer());assertEquals(5,p.size());assertTrue(p.restore(null,q.id).entries.stream().allMatch(String::isEmpty));int anchor=mark==0?start+step:start,distance=mark==0?1:mark;int[] inputs={anchor,step,distance,distance*step,answer};for(int i=0;i<5;i++)assertTrue(p.step(i).accepts(""+inputs[i]));values.add(answer);count++;}assertEquals(12221,count);assertEquals(10001,values.size());}
 @Test public void realYearFourFreshAndFullGeometryHistoryOldest(){Generator g=new Generator(new Random(143));CurriculumLimits limits=GlobalCurriculum.limits("england-primary-2021-v1",NumberLineRelations.ID,4);List<String> recent=new ArrayList<>();Set<Integer> scales=new HashSet<>();for(int i=0;i<300;i++){Question q=g.next(NumberLineRelations.ID,recent,false,limits);assertFalse(recent.contains(q.signature()));recent.add(q.signature());scales.add((int)q.diagram.values[1]);}assertEquals(Set.of(1,10,100,1000),scales);Map<String,Integer> full=new LinkedHashMap<>();int position=0;for(int step:new int[]{1,10,100,1000})for(int start=0;start+10*step<=10000;start+=10*step)for(int mark=0;mark<=10;mark++)full.put(NumberLineRelations.make(start,step,mark).signature(),position++);assertEquals(full.keySet().iterator().next(),NumberLineRelations.next(new Random(1),limits,full).signature());}
 @Test public void malformedLargeGeometryCannotBorrowKeys(){Question q=NumberLineRelations.make(0,1000,5);for(double[] values:new double[][]{{0,10000,10,5},{1000,1000,10,5},{0,1000,10,10.5},{Double.NaN,1000,10,2}}){q.diagram=new StudyDiagram("primaryNumberLine",values);q.answers=new String[]{"0"};assertNull(NumberLineRelations.read(q));assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(q,List.of(),List.of("0")).status);}}
}
